import{_ as a,o as e,c as r,a3 as d}from"./chunks/framework.Dj4Lt7vj.js";const p=JSON.parse('{"title":"工作台总览","description":"","frontmatter":{"title":"工作台总览"},"headers":[],"relativePath":"workspace/overview.md","filePath":"workspace/overview.md","lastUpdated":1787948622000}'),o={name:"workspace/overview.md"};function i(h,t,l,s,c,n){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="工作台总览" tabindex="-1">工作台总览 <a class="header-anchor" href="#工作台总览" aria-label="Permalink to &quot;工作台总览&quot;">​</a></h1><p>网页工作台是浏览器里的管理后台。人不在接待电脑旁时，可以随时登录查看数据、调整配置。</p><div class="tip custom-block"><p class="custom-block-title">工作台不做接待</p><p>接待本身在桌面客户端运行。工作台负责「看」和「配」，改动会同步到客户端生效。</p></div><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><p>打开 <a href="https://www.yizhi.chat/" target="_blank" rel="noreferrer">www.yizhi.chat</a>，用注册的手机号登录，即进入工作台。</p><h2 id="功能分区" tabindex="-1">功能分区 <a class="header-anchor" href="#功能分区" aria-label="Permalink to &quot;功能分区&quot;">​</a></h2><p>工作台顶部按三组组织标签页：</p><h3 id="常用功能" tabindex="-1">常用功能 <a class="header-anchor" href="#常用功能" aria-label="Permalink to &quot;常用功能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标签</th><th>作用</th></tr></thead><tbody><tr><td>运营助手</td><td>对话式配置副驾：帮你配方案、查异常回复、整理知识库</td></tr><tr><td>仪表盘</td><td>查看核心统计、接待数据和待处理事项</td></tr><tr><td>数据分析</td><td>工具调用次数、转接对象占比与转接成功率</td></tr><tr><td>聊天记录</td><td>按平台和顾客查看客户对话记录，见<a href="/aicare-docs/workspace/records">聊天记录与数据</a></td></tr><tr><td>知识库</td><td>集中管理可复用的店铺资料，见<a href="/aicare-docs/workspace/knowledge">管理知识库</a></td></tr></tbody></table><h3 id="ai-接待" tabindex="-1">AI 接待 <a class="header-anchor" href="#ai-接待" aria-label="Permalink to &quot;AI 接待&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标签</th><th>作用</th></tr></thead><tbody><tr><td>AI方案</td><td>设置接待规则、标准回复和人工接手，见<a href="/aicare-docs/workspace/solutions">管理 AI 方案</a></td></tr><tr><td>商品信息</td><td>维护商品参数、卖点、尺码和售后说明</td></tr><tr><td>表格</td><td>管理供智能体使用的查询表与登记表，见<a href="/aicare-docs/solution/tables">查询表与登记表</a></td></tr><tr><td>催付提醒</td><td>设置催付、回访等自动提醒</td></tr><tr><td>对话测试</td><td>用真实顾客问法检查 AI 能否答上来</td></tr></tbody></table><h3 id="店铺维护" tabindex="-1">店铺维护 <a class="header-anchor" href="#店铺维护" aria-label="Permalink to &quot;店铺维护&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标签</th><th>作用</th></tr></thead><tbody><tr><td>通知</td><td>处理公告、业务提醒和异常消息；含微信通知绑定入口</td></tr><tr><td>异常记录</td><td>查看接待异常和需要跟进的问题</td></tr><tr><td>设备</td><td>查看各台电脑的在线状态、版本和坐席</td></tr><tr><td>账单</td><td>查看剩余点数、兑换权益和开通记录，见<a href="/aicare-docs/workspace/billing">查看账单</a></td></tr></tbody></table><h2 id="运营助手" tabindex="-1">运营助手 <a class="header-anchor" href="#运营助手" aria-label="Permalink to &quot;运营助手&quot;">​</a></h2><p>「运营助手」和客户端里的「AI 助手」是同一个能力：用聊天的方式问它店铺配置、让它检查知识库、请它提修改建议。它的修改建议<strong>需要你确认后才生效</strong>，已应用的修改可以撤销。</p><h2 id="用语差异说明" tabindex="-1">用语差异说明 <a class="header-anchor" href="#用语差异说明" aria-label="Permalink to &quot;用语差异说明&quot;">​</a></h2><p>工作台和客户端个别用词不同，指的是同一个东西：</p><ul><li>工作台的「AI方案」里可能把方案下的回复角色叫「接待角色」，客户端里叫「智能体」或「情景」。</li><li>工作台「对话测试」对应客户端方案编辑器里的「对话测试」。</li></ul>',18)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
